/**
 * PASS 87 — NAYLOR 2026 REPLAY DB WRITE
 * Persists Alec Naylor's weekly P60 replay rows and April monthly settlement.
 *
 * Source of truth: games/bo_naylor-2026.json generated by
 * scripts/replay-bohm-2026.mjs --write-json.
 *
 * Usage:
 *   node scripts/write-bohm-2026-replay.mjs --dry-run
 *   node scripts/write-bohm-2026-replay.mjs
 */

import { readFileSync } from "fs"
import { join, dirname } from "path"
import { fileURLToPath } from "url"
import { createClient } from "@supabase/supabase-js"

const __dirname = dirname(fileURLToPath(import.meta.url))
const ROOT = join(__dirname, "..")
const DRY_RUN = process.argv.includes("--dry-run")
const PLAYER_ID = "bo_naylor"
const ENGINE_VERSION = "P60"
const SEASON = 2026

function loadEnv(filePath) {
  try {
    const raw = readFileSync(filePath, "utf8")
    const env = {}
    for (const line of raw.split("\n")) {
      const trimmed = line.trim()
      if (!trimmed || trimmed.startsWith("#")) continue
      const idx = trimmed.indexOf("=")
      if (idx === -1) continue
      const key = trimmed.slice(0, idx).trim()
      let val = trimmed.slice(idx + 1).trim()
      if ((val.startsWith('"') && val.endsWith('"')) || (val.startsWith("'") && val.endsWith("'"))) val = val.slice(1, -1)
      env[key] = val
    }
    return env
  } catch {
    return {}
  }
}

const env = { ...loadEnv(join(ROOT, ".env")), ...loadEnv(join(ROOT, ".env.local")) }
const SUPABASE_URL = env.NEXT_PUBLIC_SUPABASE_URL ?? ""
const SERVICE_KEY = env.SUPABASE_SERVICE_ROLE_KEY ?? ""
const CONFIGURED = SUPABASE_URL.startsWith("https://") && SERVICE_KEY.length > 0

const replay = JSON.parse(readFileSync(join(ROOT, "games", "bo_naylor-2026.json"), "utf8"))
const weeklyRows = replay.weeklyRows
const monthlyRow = replay.aprilSettlement

function buildWeeklyPayload(row) {
  return {
    player_id: PLAYER_ID,
    snapshot_week: row.snapshot_week,
    engine_version: ENGINE_VERSION,
    dlr_score: row.dlr_score,
    dlr_tier: row.dlr_tier,
    confidence_level: row.confidence_level,
    confidence_overall: row.confidence_overall,
    confidence_knowledge: row.confidence_knowledge,
    confidence_performance: row.confidence_performance,
    confidence_media: row.confidence_media,
    confidence_market: row.confidence_market,
    health_class: row.health_class,
    fallback_used: row.fallback_used,
    base_dlr: row.base_dlr,
    weekly_delta: row.weekly_delta,
    monthly_contribution: row.monthly_contribution,
    weekly_history: row.weekly_history,
    large_movement: row.large_movement ?? false,
    competition_level: row.competition_level,
    source: "manual",
    season: SEASON,
  }
}

function buildMonthlyPayload(row) {
  return {
    player_id: PLAYER_ID,
    engine_version: ENGINE_VERSION,
    settlement_month: row.settlement_month,
    dlr_score: row.dlr_score,
    dlr_tier: row.dlr_tier,
    week_count: row.week_count,
    confidence_level: row.confidence_level,
    health_class: row.health_class,
    weekly_avg_delta: row.weekly_avg_delta,
    monthly_contribution: row.monthly_contribution,
    weekly_history: row.weekly_history,
    source: row.source,
    season: row.season,
  }
}

console.log(`=== PASS 87 NAYLOR 2026 REPLAY ${DRY_RUN ? "DRY-RUN" : "LIVE WRITE"} ===`)
console.log(`Player: ${PLAYER_ID}`)
console.log(`Engine: ${ENGINE_VERSION}`)
console.log(`Rows: ${weeklyRows.length} weekly + 1 monthly`)
console.log(`Final DLR: ${weeklyRows.at(-1)?.dlr_score}`)

for (const row of weeklyRows) {
  const p = buildWeeklyPayload(row)
  console.log(`  ${p.snapshot_week} dlr=${p.dlr_score} Δ=${p.weekly_delta >= 0 ? "+" : ""}${p.weekly_delta} conf=${p.confidence_level} hist=${JSON.stringify(p.weekly_history)}`)
}
console.log(`  ${monthlyRow.settlement_month} monthly dlr=${monthlyRow.dlr_score} avgΔ=${monthlyRow.weekly_avg_delta}`)

if (DRY_RUN) {
  console.log("[DRY-RUN] No Supabase writes performed.")
  process.exit(0)
}

if (!CONFIGURED) {
  console.error("ERROR: Supabase not configured. Check .env/.env.local.")
  process.exit(1)
}

const sb = createClient(SUPABASE_URL, SERVICE_KEY)

const { data: playerRow, error: playerError } = await sb
  .from("players")
  .select("id, name, dlr_score")
  .eq("id", PLAYER_ID)
  .maybeSingle()

if (playerError || !playerRow) {
  console.error(`HALT: players row missing for ${PLAYER_ID}: ${playerError?.message ?? "not found"}`)
  process.exit(1)
}

console.log(`Player confirmed: ${playerRow.name} (current dlr_score=${playerRow.dlr_score ?? "null"})`)

let weeklyOk = 0
for (const row of weeklyRows) {
  const { error } = await sb
    .from("player_dlr_weekly")
    .upsert(buildWeeklyPayload(row), { onConflict: "player_id,snapshot_week,engine_version" })
  if (error) {
    console.error(`FAIL ${row.snapshot_week}: ${error.message}`)
  } else {
    console.log(`OK   ${row.snapshot_week} dlr=${row.dlr_score} Δ=${row.weekly_delta >= 0 ? "+" : ""}${row.weekly_delta}`)
    weeklyOk++
  }
}

const { error: monthlyError } = await sb
  .from("player_dlr_monthly")
  .upsert(buildMonthlyPayload(monthlyRow), { onConflict: "player_id,settlement_month,engine_version" })

if (monthlyError) console.error(`FAIL ${monthlyRow.settlement_month}: ${monthlyError.message}`)
else console.log(`OK   ${monthlyRow.settlement_month} monthly dlr=${monthlyRow.dlr_score}`)

const latestWeek = weeklyRows.at(-1)
const { error: cacheError } = await sb
  .from("players")
  .update({ dlr_score: latestWeek.dlr_score, updated_at: new Date().toISOString() })
  .eq("id", PLAYER_ID)

if (cacheError) console.warn(`WARN players.dlr_score update failed: ${cacheError.message}`)
else console.log(`OK   players.dlr_score → ${latestWeek.dlr_score}`)

console.log(`Complete: ${weeklyOk}/${weeklyRows.length} weekly OK, monthly ${monthlyError ? "FAIL" : "OK"}`)

